import fs from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {execFileSync} from 'node:child_process';
import {resolve,relative,isAbsolute,dirname} from 'node:path';
export const hash=b=>createHash('sha256').update(b).digest('hex');
export function safePath(root,path){if(typeof path!=='string'||!path||isAbsolute(path)||path.includes('\\')||path.split('/').some(p=>p==='..'||p==='.'))throw Error('UNSAFE_PATH');const target=resolve(root,path),r=relative(root,target);if(!r||r.startsWith('..')||isAbsolute(r))throw Error('PATH_ESCAPE');return target;}
export async function rawFile(root,path){const target=safePath(root,path),real=await fs.realpath(target);if(real!==target)throw Error('SYMLINK_PATH');return fs.readFile(target);}
export async function candidateSnapshot(root){const git=args=>execFileSync('git',args,{cwd:root,encoding:'utf8',maxBuffer:32*1024*1024});const paths=[...new Set([...git(['ls-files','-z']).split('\0'),...git(['ls-files','--others','--exclude-standard','-z']).split('\0')].filter(Boolean))].sort();const identity={head:git(['rev-parse','HEAD']).trim(),branch:git(['branch','--show-current']).trim(),status:git(['status','--short']).trimEnd(),cachedNames:git(['diff','--cached','--name-only']).trim()};if(identity.cachedNames)throw Error('STAGED_CHANGES');const artifacts=[];for(const path of paths){const b=await rawFile(root,path);artifacts.push({path,bytes:b.length,sha256:hash(b)});}const state={identity,artifacts};return {...state,digest:hash(JSON.stringify(state))};}
export async function packetSnapshot(root){const artifacts=[];const walk=async path=>{for(const e of await fs.readdir(resolve(root,path),{withFileTypes:true})){const child=path?path+'/'+e.name:e.name;if(e.isSymbolicLink())throw Error('SYMLINK_PACKET');if(e.isDirectory())await walk(child);else if(e.isFile()){const b=await rawFile(root,child);artifacts.push({path:child,bytes:b.length,sha256:hash(b)});}else throw Error('NONREGULAR_PACKET');}};await walk('');artifacts.sort((a,b)=>a.path<b.path?-1:a.path>b.path?1:0);return {artifacts,digest:hash(JSON.stringify(artifacts))};}
export async function verifyPacketSource(candidate,packet,manifest){const seen=new Set();for(const a of manifest.artifacts){if(seen.has(a.path))throw Error('DUPLICATE_PATH');seen.add(a.path);for(const root of [candidate,packet]){const b=await rawFile(root,a.path);if(b.length!==a.bytes||hash(b)!==a.sha256)throw Error('SOURCE_OR_PACKET_DRIFT:'+a.path);}}return seen.size;}

